from langchain_openai import ChatOpenAI

    llm = ChatOpenAI(model=llm_model_name) 
    calculate = get_math_tool(llm)



    search = TavilySearchResults(
        max_results=1,
        description='tavily_search_results_json(query="the search query") - a search engine.',
    )

    tools = [search, calculate]




    # Part 2: Planner
    # region Planner
    from typing import Sequence

    from langchain import hub
    from langchain_core.language_models import BaseChatModel
    from langchain_core.messages import (
        BaseMessage,
        FunctionMessage,
        HumanMessage,
        SystemMessage,
    )
    from langchain_core.prompts import ChatPromptTemplate
    from langchain_core.runnables import RunnableBranch
    from langchain_core.tools import BaseTool
    from langchain_openai import ChatOpenAI
    from utils.llm_compiler_output_parser import LLMCompilerPlanParser, Task

    prompt = hub.pull("wfh/llm-compiler")



    def create_planner(
    llm: BaseChatModel, tools: Sequence[BaseTool], base_prompt: ChatPromptTemplate
):
        tool_descriptions = "\n".join(
            f"{i+1}. {tool.description}\n"
            for i, tool in enumerate(
                tools
            )  # +1 to offset the 0 starting index, we want it count normally from 1.
        )
        planner_prompt = base_prompt.partial(
            replan="",
            num_tools=len(tools)
            + 1,  # Add one because we're adding the join() tool at the end.
            tool_descriptions=tool_descriptions,
        )
        replanner_prompt = base_prompt.partial(
            replan=' - You are given "Previous Plan" which is the plan that the previous agent created along with the execution results '
            "(given as Observation) of each plan and a general thought (given as Thought) about the executed results."
            'You MUST use these information to create the next plan under "Current Plan".\n'
            ' - When starting the Current Plan, you should start with "Thought" that outlines the strategy for the next plan.\n'
            " - In the Current Plan, you should NEVER repeat the actions that are already executed in the Previous Plan.\n"
            " - You must continue the task index from the end of the previous one. Do not repeat task indices.", # type: ignore
            num_tools=len(tools) + 1,
            tool_descriptions=tool_descriptions,
        )

        def should_replan(state: list):
            # Context is passed as a system message
            return isinstance(state[-1], SystemMessage)

        def wrap_messages(state: list):
            return {"messages": state}

        def wrap_and_get_last_index(state: list):
            next_task = 0
            for message in state[::-1]:
                if isinstance(message, FunctionMessage):
                    next_task = message.additional_kwargs["idx"] + 1
                    break
            state[-1].content = state[-1].content + f" - Begin counting at : {next_task}"
            return {"messages": state}

        return (
            RunnableBranch(
                (should_replan, wrap_and_get_last_index | replanner_prompt),
                wrap_messages | planner_prompt,
            )
            | llm
            | LLMCompilerPlanParser(tools=tools)
        )



    # This is the primary "agent" in our application
    planner = create_planner(llm, tools, prompt)

    # endregion

    # 3. Task Fetching Unit
    # region Task Fetching Unit
    import re
    import time
    from concurrent.futures import ThreadPoolExecutor, wait
    from typing import Any, Dict, Iterable, List, Union

    from langchain_core.runnables import (
        chain as as_runnable,
    )
    from typing_extensions import TypedDict


    def _get_observations(messages: List[BaseMessage]) -> Dict[int, Any]:
        # Get all previous tool responses
        results = {}
        for message in messages[::-1]:
            if isinstance(message, FunctionMessage):
                results[int(message.additional_kwargs["idx"])] = message.content
        return results


    class SchedulerInput(TypedDict):
        messages: List[BaseMessage]
        tasks: Iterable[Task]


    def _execute_task(task, observations, config):
        tool_to_use = task["tool"]
        if isinstance(tool_to_use, str):
            return tool_to_use
        args = task["args"]
        try:
            if isinstance(args, str):
                resolved_args = _resolve_arg(args, observations)
            elif isinstance(args, dict):
                resolved_args = {
                    key: _resolve_arg(val, observations) for key, val in args.items()
                }
            else:
                # This will likely fail
                resolved_args = args
        except Exception as e:
            return (
                f"ERROR(Failed to call {tool_to_use.name} with args {args}.)"
                f" Args could not be resolved. Error: {repr(e)}"
            )
        try:
            return tool_to_use.invoke(resolved_args, config)
        except Exception as e:
            return (
                f"ERROR(Failed to call {tool_to_use.name} with args {args}."
                + f" Args resolved to {resolved_args}. Error: {repr(e)})"
            )


    def _resolve_arg(arg: Union[str, Any], observations: Dict[int, Any]):
        # $1 or ${1} -> 1
        ID_PATTERN = r"\$\{?(\d+)\}?"

        def replace_match(match):
            # If the string is ${123}, match.group(0) is ${123}, and match.group(1) is 123.

            # Return the match group, in this case the index, from the string. This is the index
            # number we get back.
            idx = int(match.group(1))
            return str(observations.get(idx, match.group(0)))

        # For dependencies on other tasks
        if isinstance(arg, str):
            return re.sub(ID_PATTERN, replace_match, arg)
        elif isinstance(arg, list):
            return [_resolve_arg(a, observations) for a in arg]
        else:
            return str(arg)


    @as_runnable
    def schedule_task(task_inputs, config):
        task: Task = task_inputs["task"]
        observations: Dict[int, Any] = task_inputs["observations"]
        try:
            observation = _execute_task(task, observations, config)
        except Exception:
            import traceback

            observation = traceback.format_exception()  # repr(e) +
        observations[task["idx"]] = observation


    def schedule_pending_task(
        task: Task, observations: Dict[int, Any], retry_after: float = 0.2
    ):
        while True:
            deps = task["dependencies"]
            if deps and (any([dep not in observations for dep in deps])):
                # Dependencies not yet satisfied
                time.sleep(retry_after)
                continue
            schedule_task.invoke({"task": task, "observations": observations})
            break


    @as_runnable
    def schedule_tasks(scheduler_input: SchedulerInput) -> List[FunctionMessage]:
        """Group the tasks into a DAG schedule."""
        # For streaming, we are making a few simplifying assumption:
        # 1. The LLM does not create cyclic dependencies
        # 2. That the LLM will not generate tasks with future deps
        # If this ceases to be a good assumption, you can either
        # adjust to do a proper topological sort (not-stream)
        # or use a more complicated data structure
        tasks = scheduler_input["tasks"]
        args_for_tasks = {}
        messages = scheduler_input["messages"]
        # If we are re-planning, we may have calls that depend on previous
        # plans. Start with those.
        observations = _get_observations(messages)
        task_names = {}
        originals = set(observations)
        # ^^ We assume each task inserts a different key above to
        # avoid race conditions...
        futures = []
        retry_after = 0.25  # Retry every quarter second
        with ThreadPoolExecutor() as executor:
            for task in tasks:
                deps = task["dependencies"]
                task_names[task["idx"]] = (
                    task["tool"] if isinstance(task["tool"], str) else task["tool"].name
                )
                args_for_tasks[task["idx"]] = task["args"]
                if (
                    # Depends on other tasks
                    deps
                    and (any([dep not in observations for dep in deps]))
                ):
                    futures.append(
                        executor.submit(
                            schedule_pending_task, task, observations, retry_after
                        )
                    )
                else:
                    # No deps or all deps satisfied
                    # can schedule now
                    schedule_task.invoke(dict(task=task, observations=observations))
                    # futures.append(executor.submit(schedule_task.invoke dict(task=task, observations=observations)))

            # All tasks have been submitted or enqueued
            # Wait for them to complete
            wait(futures)
        # Convert observations to new tool messages to add to the state
        new_observations = {
            k: (task_names[k], args_for_tasks[k], observations[k])
            for k in sorted(observations.keys() - originals)
        }
        tool_messages = [
            FunctionMessage(
                name=name, content=str(obs), additional_kwargs={"idx": k, "args": task_args}
            )
            for k, (name, task_args, obs) in new_observations.items()
        ]
        return tool_messages
    

    import itertools


    @as_runnable
    def plan_and_schedule(state):
        messages = state["messages"]
        tasks = planner.stream(messages)
        # Begin executing the planner immediately
        try:
            tasks = itertools.chain([next(tasks)], tasks)
        except StopIteration:
            # Handle the case where tasks is empty.
            tasks = iter([])
        scheduled_tasks = schedule_tasks.invoke(
            {
                "messages": messages,
                "tasks": tasks,
            }
        )
        return {"messages": [scheduled_tasks]}
    
    # endregion
    
    # 4. "Joiner"
    # region Joiner
    from langchain.chains.openai_functions import create_structured_output_runnable
    from   langchain_core.messages import AIMessage
    from langchain_core.pydantic_v1 import BaseModel, Field


    class FinalResponse(BaseModel):
        """The final response/answer."""

        response: str


    class Replan(BaseModel):
        feedback: str = Field(
            description="Analysis of the previous attempts and recommendations on what needs to be fixed."
        )


    class JoinOutputs(BaseModel):
        """Decide whether to replan or whether you can return the final response."""

        thought: str = Field(
            description="The chain of thought reasoning for the selected action"
        )
        action: Union[FinalResponse, Replan]


    joiner_prompt = hub.pull("wfh/llm-compiler-joiner").partial(
        examples=""
    )  # You can optionally add examples
    

    runnable = create_structured_output_runnable(JoinOutputs, llm, joiner_prompt)

    
    # We will select only the most recent messages in the state, and format the output to be more useful for the planner, should the agent need to loop.
    def _parse_joiner_output(decision: JoinOutputs) -> List[BaseMessage]:
        response = [AIMessage(content=f"Thought: {decision.thought}")]
        if isinstance(decision.action, Replan):
            return response + [
                SystemMessage(
                    content=f"Context from last attempt: {decision.action.feedback}"
                )
            ]
        else:
            return {"messages": response + [AIMessage(content=decision.action.response)]}


    def select_recent_messages(state) -> dict:
        messages = state["messages"]
        selected = []
        for msg in messages[::-1]:
            selected.append(msg)
            if isinstance(msg, HumanMessage):
                break
        return {"messages": selected[::-1]}


    joiner = select_recent_messages | runnable | _parse_joiner_output

    # endregion

    # 5. Compose using LangGraph
    # region LangGraph
    from langgraph.graph import END, StateGraph, START
    from langgraph.graph.message import add_messages
    from typing import Annotated


    class State(TypedDict):
        messages: Annotated[list, add_messages]

    from langgraph.graph import MessageGraph, END
    graph_builder = StateGraph(State)
    # graph_builder = MessageGraph()

    # 1.  Define vertices
    # We defined plan_and_schedule above already
    # Assign each node to a state variable to update
    graph_builder.add_node("plan_and_schedule", plan_and_schedule)
    graph_builder.add_node("join", joiner)


    ## Define edges
    graph_builder.add_edge("plan_and_schedule", "join")

    ### This condition determines looping logic


    # def should_continue(state):
    #     messages = state["messages"]
    #     if isinstance(messages[-1], AIMessage):
    #         return END
    #     return "plan_and_schedule"

    from langgraph.graph import END, StateGraph, MessagesState
    from typing import Annotated, Literal, TypedDict
    
        # Define the function that determines whether to continue or not
    # def should_continue(state: MessagesState) -> Literal["plan_and_schedule", END]:
    #     messages = state['messages']
    #     last_message = messages[-1]
    #     if isinstance(messages[-1], AIMessage):
    #         return END
    #     return "plan_and_schedule"

    def should_continue(state: List[BaseMessage]):
        if isinstance(state[-1], AIMessage):
            return END
        return "plan_and_schedule"



    graph_builder.add_conditional_edges(
        "join",
        # Next, we pass in the function that will determine which node is called next.
        should_continue)
    graph_builder.add_edge(START, "plan_and_schedule")
    
    chain = graph_builder.compile()
    #endregion



    steps = chain.stream(
        {"messages": HumanMessage(content="What's the oldest parrot alive, and how much longer is that than the average?")},
        {
            "recursion_limit": 100,
        }
    )
    for step in steps:
        print(step)
        print("---")
    # final_state = chain.invoke(
    # {"messages": [HumanMessage(content="what is the weather in sf")]},
    # config={"configurable": {"thread_id": 42}}
    # )
    # print(final_state["messages"][-1].content)
    # print(steps[-1])

    response = dict()
    response['answer'] = ''
    response['context'] = ''

    return(response)
    
    # response['answer'] = final_state["messages"][-1].content
    # response['context'] = [x.content for x in final_state["messages"]

    #     Conclusion
    # The planner output parsing format is fragile if your function requires more than 1 or 2 arguments. We could make it more robust by using streaming tool calling.
    # Variable substitution is fragile in the example above. It could be made more robust by using a fine-tuned model and a more robust syntax (using e.g., Lark or a tool calling schema)
    # The state can grow quite long if you require multiple re-planning runs. To handle, you could add a message compressor once you go above a certain token limit.
